<?php
session_start();
$allowedOrigins=['http://localhost:5173','http://localhost:5174'];$origin=$_SERVER['HTTP_ORIGIN']??'';if(in_array($origin,$allowedOrigins,true)){header("Access-Control-Allow-Origin: $origin");header("Access-Control-Allow-Credentials: true");}header('Access-Control-Allow-Methods: GET, OPTIONS');header('Access-Control-Allow-Headers: Content-Type');header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(200);exit;}
require_once __DIR__.'/../config/database.php';$isAdmin=isset($_SESSION['admin_user_id']);
try{$sql='SELECT p.id,p.name,p.slug,p.description,p.price,p.discount_price,p.width,p.height,p.medium,p.frame,p.gold_details,p.stock,p.is_featured,p.is_active,p.created_at,c.name AS category_name FROM paintings p LEFT JOIN categories c ON c.id=p.category_id';if(!$isAdmin)$sql.=' WHERE p.is_active=1';$sql.=' ORDER BY p.created_at DESC';$paintings=$pdo->query($sql)->fetchAll();$imageStmt=$pdo->prepare('SELECT id,image_url,sort_order,is_primary FROM painting_images WHERE painting_id=? ORDER BY sort_order ASC,id ASC');$sizeStmt=$pdo->prepare('SELECT id,name,width,height,unit,price,is_standard,sort_order FROM painting_size_options WHERE painting_id=? ORDER BY sort_order ASC,id ASC');foreach($paintings as &$painting){$imageStmt->execute([$painting['id']]);$painting['images']=$imageStmt->fetchAll();$painting['image_url']=!empty($painting['images'])?$painting['images'][0]['image_url']:null;$sizeStmt->execute([$painting['id']]);$painting['size_options']=$sizeStmt->fetchAll();}unset($painting);echo json_encode(['success'=>true,'paintings'=>$paintings]);}catch(Throwable $e){error_log('Painting list error: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Unable to load paintings']);}
